from pathlib import Path
import hashlib,json,re
import markdown
from bs4 import BeautifulSoup
ROOT=Path(__file__).resolve().parents[4];OUT=Path(__file__).resolve().parent
read=lambda p:p.read_text(encoding='utf-8-sig')
files={'tutorial':'commons/maps/Point_One/tutorial.md','main':'commons/maps/Point_One/final.md'}
texts={k:read(OUT/'sources'/v) for k,v in files.items()}
def render(text,prefix):
    soup=BeautifulSoup(markdown.markdown(text,extensions=['extra']),'html.parser')
    for tag in soup.find_all(id=True):tag['id']=prefix+'-'+tag['id']
    for tag in soup.find_all('a',href=True):
        if tag['href'].startswith('#'):tag['href']='#'+prefix+'-'+tag['href'][1:]
    return str(soup)
css="""
:root{--ground:#e6e7e1;--paper:#fcfaf4;--ink:#242b2c;--muted:#6f7774;--line:#d3d5cb;--accent:#305b53;color-scheme:light}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:100px}body{margin:0;background:var(--ground);color:var(--ink);font:18px/1.7 Georgia,serif}a{color:var(--accent);text-underline-offset:3px}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #99636c;outline-offset:4px}.bar{background:rgba(252,250,244,.97);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:2}.bar-inner{max-width:1500px;margin:auto;padding:16px 28px;display:flex;justify-content:space-between;align-items:center;gap:16px}.identity,.controls,summary,footer,.folio,.source,.note{font-family:system-ui,sans-serif}.identity{font-size:13px;letter-spacing:.04em}.identity span{color:var(--muted);padding-left:12px}.controls{display:flex;border:1px solid var(--line);border-radius:4px;padding:3px;gap:4px}.controls button{cursor:pointer;font:12px/1.4 system-ui,sans-serif;border:0;padding:8px 12px;border-radius:2px;background:transparent;color:var(--ink)}.controls button[aria-pressed=true]{color:white;background:var(--accent)}.note{max-width:1460px;margin:22px auto 18px;padding:0 28px;font-size:13px;line-height:1.6;color:#5a625f}.book{max-width:1460px;margin:0 auto 40px;padding:0 22px;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;align-items:start}.page{min-width:0;background:var(--paper);padding:34px clamp(25px,3.5vw,58px) 50px;box-shadow:0 3px 14px #23322912}.page-left{border-radius:3px 0 0 3px;background:linear-gradient(to right,var(--paper) 96%,#f0eee7)}.page-right{border-radius:0 3px 3px 0;background:linear-gradient(to left,var(--paper) 96%,#f0eee7)}.folio{display:flex;justify-content:space-between;gap:14px;font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);padding-bottom:18px;border-bottom:1px solid var(--line);margin-bottom:32px}.folio strong{font-weight:600;color:var(--accent)}h1{font-weight:400;font-size:32px;line-height:1.2;letter-spacing:-.015em;margin:0 0 28px}h2{font-size:25px;line-height:1.3;font-weight:400;margin:34px 0 19px}p{margin:0 0 22px}pre{font:12px/1.7 Consolas,monospace;background:#eef0e9;border-left:2px solid #9caf9e;margin:20px 0 24px;padding:16px;white-space:pre-wrap;overflow-wrap:anywhere}code{font:.83em/1.5 Consolas,monospace}pre code{font:inherit}.footnote{font-size:13px;margin-top:36px;overflow-wrap:anywhere}.footnote p{margin-bottom:14px}.footnote ol{padding-left:22px}.source{font-size:11px;line-height:1.7;border-top:1px solid var(--line);padding-top:20px;margin-top:36px;color:var(--muted)}sup{line-height:0}.editorial{max-width:1000px;margin:28px auto 40px;padding:0 28px}.editorial summary{font-size:14px;color:var(--accent);cursor:pointer}.editorial div{padding-top:20px;font:15px/1.7 system-ui,sans-serif}.editorial p{margin-bottom:16px}footer{max-width:1400px;margin:0 auto;padding:12px 28px 44px;font-size:12px;color:var(--muted)}body.single .book{display:block;max-width:810px}body.single .page{background:var(--paper);border-radius:3px}body.single .page[hidden]{display:none}[hidden]{display:none!important}
@media(max-width:1000px){.page{padding:28px 28px 40px}body{font-size:17px}.book{gap:8px;padding-inline:14px}.bar-inner{padding:12px 18px}.identity span{display:none}h1{font-size:28px}}
@media(max-width:740px){.book{display:block;padding-inline:16px}.page{margin-bottom:18px;padding:28px 24px;background:var(--paper)}.bar-inner{gap:8px}.identity{font-size:11px}.controls button{padding:6px 7px;font-size:11px}.controls{gap:0}.note{padding-inline:20px}body{font-size:18px}.folio{font-size:9px}}
@media print{@page{size:A3 landscape;margin:15mm}.bar,.note,.editorial,footer,.source{display:none}body{background:white;font-size:10pt}.book{max-width:none;padding:0;gap:18mm}.page{box-shadow:none;background:white!important;padding:0;border-radius:0}h1{font-size:21pt}h2{font-size:16pt}pre{font-size:8pt;break-inside:avoid}.folio{font-size:8pt}}
"""
script="""const choices=Array.from(document.querySelectorAll('[data-view]'));const left=document.getElementById('left-page');const right=document.getElementById('right-page');function showPages(mode){document.body.classList.toggle('single',mode!=='both');left.hidden=mode==='main';right.hidden=mode==='tutorial';choices.forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.view===mode)));}choices.forEach(button=>button.addEventListener('click',()=>showPages(button.dataset.view)));"""
page=f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Point One | Tutorial on the left, main text on the right</title><style>{css}</style></head><body>
<div class="bar"><div class="bar-inner"><div class="identity">ADA RESEARCH <span>Point One / facing pages</span></div><nav class="controls" aria-label="Choose pages"><button type="button" data-view="both" aria-pressed="true">Facing pages</button><button type="button" data-view="tutorial" aria-pressed="false">Tutorial</button><button type="button" data-view="main" aria-pressed="false">Main text</button></nav></div></div>
<p class="note">Left: the existing coding tutorial. Right: the current book chapter. Both manuscripts appear in full, unchanged.</p>
<main class="book" aria-label="Point One book spread">
<article class="page page-left" id="left-page" aria-label="Left page: coding tutorial"><div class="folio"><strong>Left / Coding tutorial</strong><span>tutorial.md</span></div><div class="manuscript">{render(texts['tutorial'],'tutorial')}</div><div class="source">Existing tutorial, captured 29 September 2026. <a href="sources/commons/maps/Point_One/tutorial.md">Read the Markdown</a>.</div></article>
<article class="page page-right" id="right-page" aria-label="Right page: main text"><div class="folio"><strong>Right / Main text</strong><span>final.md</span></div><div class="manuscript">{render(texts['main'],'main')}</div><div class="source">Current chapter, captured 29 September 2026. <a href="sources/commons/maps/Point_One/final.md">Read the Markdown</a> / <a href="/compose/sources?map=Point_One&amp;doc=final">Read and comment</a>.</div></article>
</main>
<details class="editorial"><summary>What this comparison lets us judge</summary><div><p>The tutorial is the actual <code>tutorial.md</code>, including its code blocks. The right-hand text is the actual <code>final.md</code>. Neither is condensed into a sidebar or rearranged for this test.</p><p>These files currently follow different orders. The tutorial starts with axes and an origin; the main text starts with an absent, visible, solid and held point. The tutorial also contains older helper examples and a gyroscope step. Showing it here does not certify every example as a complete runnable lesson.</p><p>If the facing pages work, the next editorial step is to bring the tutorial into relation with the current encounters: give a position a visible body, add collision, make it grabbable, then read it in two reference frames. The essential explanation can remain in the main text while the left page develops the code.</p><p>These are equal facing columns for a reading test, not a finished paginated print edition. On narrow screens they stack; use the page buttons to read either text alone.</p></div></details>
<footer>Layout study / 29 September 2026 / <a href="sources.json">Source fingerprints</a> / <a href="verification.json">Publication checks</a></footer><script>{script}</script></body></html>"""
soup=BeautifulSoup(page,'html.parser');ids=[t['id'] for t in soup.find_all(id=True)]
assert len(ids)==len(set(ids))
assert all(a['href'][1:] in ids for a in soup.find_all('a',href=True) if a['href'].startswith('#'))
for key,selector in [('tutorial','#left-page .manuscript'),('main','#right-page .manuscript')]:
    expected=BeautifulSoup(render(texts[key],key),'html.parser')
    actual=soup.select_one(selector)
    assert actual.get_text()==expected.get_text()
    assert [c.get_text() for c in actual.select('pre code')]==[c.get_text() for c in expected.select('pre code')]
for file,digest in json.loads(read(OUT/'sources.json')).items():assert hashlib.sha256((ROOT/file).read_bytes()).hexdigest()==digest
(OUT/'index.html').write_text(page,encoding='utf-8')
(OUT/'reading-mode.js').write_text(script,encoding='utf-8')
(OUT/'verification.json').write_text(json.dumps({'canonical_sources_unchanged':True,'full_rendered_text_and_code_preserved':True,'tutorial_on_left':True,'main_text_on_right':True,'tutorial_code_blocks':len(soup.select('#left-page pre code')),'footnote_links_resolve':True,'browser_check':'Not performed: browser automation startup is blocked by the Windows sandbox ACL helper.'},indent=2)+'\n',encoding='utf-8')
print('Facing pages built from the actual files; both complete texts and all code blocks preserved.')
